-- Sree Sai Ram Crackers (= Kids Crackers Park) — 2026 retail price list seed.
-- Source: Retail Price list - 2026 Final.pdf, transcribed row-for-row (200 line items).
-- Archives the existing Selva Fancy Crackers catalogue (status -> 'archived', never deleted)
-- and replaces it with the 200 SSR-### products. Safe to re-run: upserts by sku.

-- ── Archive the outgoing Selva catalogue ────────────────────────────
update products set status = 'archived' where sku like 'SFC-%' and status <> 'archived';

-- ── New categories not already covered by the existing catalogue ───
on conflict (slug) do nothing;

-- ── Sree Sai Ram products ────────────────────────────────────────────
on conflict (sku) do update set
  slug = excluded.slug,
  name_en = excluded.name_en,
  category_id = excluded.category_id,
  mrp = excluded.mrp,
  unit = excluded.unit,
  is_discountable = excluded.is_discountable,
  status = excluded.status,
  display_order = excluded.display_order;

-- ── Sanity check: expect 200 total / 197 active ─────────────────────
do $$
declare
  v_total int;
  v_active int;
begin
  select count(*) into v_total from products where sku like 'SSR-%';
  select count(*) into v_active from products where sku like 'SSR-%' and status = 'active';
  if v_total <> 200 then
    raise exception 'Expected 200 SSR products, found %', v_total;
  end if;
  if v_active <> 197 then
    raise exception 'Expected 197 active SSR products, found %', v_active;
  end if;
  raise notice 'OK: % SSR products, % active', v_total, v_active;
end $$;

